144:     if (!QFileInfo::exists(filePath)) {
145:         return;
146:     }
147: 
148:     m_mediaTitleLabel->setText(title.isEmpty() ? QFileInfo(filePath).fileName() : title);
149:     m_audioTitleLabel->setText(m_mediaTitleLabel->text());
150: 
151:     QString ext = QFileInfo(filePath).suffix().toLower();
152:     bool isAudio = isAudioOnly || (ext == "mp3" || ext == "m4a" || ext == "wav" || ext == "flac" || ext == "aac" || ext == "ogg");
153: 
154:     if (isAudio) {
155:         m_displayStack->setCurrentIndex(1); // Audio mode
156:         m_displayStack->setMaximumHeight(140);
157:         m_displayStack->setMinimumHeight(120);
158:     } else {
159:         m_displayStack->setCurrentIndex(0); // Video mode
160:         m_displayStack->setMinimumHeight(220);
161:         m_displayStack->setMaximumHeight(360);
162:     }
