    if (m_totalPlaylistItems > 0) {
        speed = QString("[%1/%2] %3").arg(m_currentPlaylistItem).arg(m_totalPlaylistItems).arg(speed);
    }
    emit progressUpdated(m_task.id, percent, speed, eta);
}

