    outline: none;
}

/* --- Window & Page Layout --- */
QMainWindow, QDialog {
    background-color: #fcf6ec;
}

QWidget#centralWidget, QWidget#pageContainer {
    background-color: #fcf6ec;
}

QScrollArea {
    background-color: #fcf6ec;
    border: none;
}

QScrollArea > QWidget > QWidget {
    background-color: #fcf6ec;
}

/* --- Sidebar Navigation --- */
QWidget#sidebarContainer {
    background-color: #f7e4c6;
    border-right: 1px solid #e0c8a6;
}

QPushButton#navButton {
    background-color: transparent;
    border: none;
    border-radius: 8px;
    color: #5c4033;
    font-size: 13px;
    font-weight: 500;
    text-align: left;
    padding: 10px 16px;
    margin: 2px 8px;
}

QPushButton#navButton:hover {
    background-color: #ffebc2;
    color: #1a110f;
}

QPushButton#navButton:checked {
    background-color: #ffebc2;
    color: #945e38;
    font-weight: 700;
    border-left: 3px solid #945e38;
}

/* --- Card Containers --- */
QFrame#cardFrame, QWidget#cardFrame {
    background-color: #ffffff;
    border: 1px solid #e5ccae;
    border-radius: 10px;
    padding: 16px;
}

QFrame#downloadCard {
    background-color: #ffffff;
    border: 1px solid #e5ccae;
    border-radius: 10px;
    padding: 14px;
}

QFrame#downloadCard:hover {
    border-color: #945e38;
}

/* --- Inputs --- */
QLineEdit {
    background-color: #ffffff;
    border: 1.5px solid #d4b896;
    border-radius: 8px;
    padding: 9px 14px;
    color: #1a110f;
    font-size: 13.5px;
    selection-background-color: #ffebc2;
    selection-color: #1a110f;
}

QLineEdit:focus {
    border: 2px solid #945e38;
}

QLineEdit::placeholder {
    color: #9c836e;
}

QComboBox, QSpinBox {
    background-color: #ffffff;
    border: 1px solid #d4b896;
    border-radius: 8px;
    padding: 8px 12px;
    color: #1a110f;
    font-size: 13px;
    min-height: 22px;
}

QComboBox:focus, QSpinBox:focus {
    border: 1.5px solid #945e38;
}

QComboBox::drop-down {
    subcontrol-origin: padding;
    subcontrol-position: top right;
    width: 28px;
    border-left: 1px solid #e5ccae;
    border-top-right-radius: 8px;
    border-bottom-right-radius: 8px;
}

QComboBox QAbstractItemView {
    background-color: #ffffff;
    border: 1px solid #e5ccae;
    border-radius: 8px;
    selection-background-color: #ffebc2;
    selection-color: #945e38;
    padding: 6px;
}

QCheckBox {
    color: #1a110f;
    font-size: 13px;
}

QCheckBox::indicator {
    width: 18px;
    height: 18px;
    border: 1.5px solid #d4b896;
    border-radius: 4px;
    background-color: #ffffff;
