    font-size: 11.5px;
    font-weight: 600;
}

QLabel#statusCompleted {
    background-color: #f0f8ff;
    color: #0284c7;
    border: 1px solid #7cc6fe;
    border-radius: 6px;
    padding: 3px 8px;
    font-size: 11.5px;
    font-weight: 600;
}

QLabel#statusFailed {
    background-color: #fef2f2;
    color: #b91c1c;
    border: 1px solid #fecaca;
    border-radius: 6px;
    padding: 3px 8px;
    font-size: 11.5px;
    font-weight: 600;
