package com.pullar.app.data.dao

import androidx.room.Dao
import androidx.room.Delete
import androidx.room.Insert
import androidx.room.OnConflictStrategy
import androidx.room.Query
import androidx.room.Update
import com.pullar.app.data.model.DownloadEntity
import com.pullar.app.data.model.DownloadStatus
import kotlinx.coroutines.flow.Flow

@Dao
interface DownloadDao {

    @Query("SELECT * FROM downloads WHERE status IN ('QUEUED', 'ANALYZING', 'DOWNLOADING', 'PAUSED') ORDER BY createdAt ASC")
    fun getActiveDownloads(): Flow<List<DownloadEntity>>

    @Query("SELECT * FROM downloads WHERE status = 'COMPLETED' ORDER BY createdAt DESC")
    fun getHistory(): Flow<List<DownloadEntity>>

    @Query("SELECT * FROM downloads WHERE status = 'COMPLETED' AND title LIKE '%' || :query || '%' ORDER BY createdAt DESC")
    fun searchHistory(query: String): Flow<List<DownloadEntity>>

    @Query("SELECT * FROM downloads WHERE id = :id LIMIT 1")
    suspend fun getById(id: String): DownloadEntity?

    @Query("SELECT * FROM downloads WHERE url = :url AND status IN ('QUEUED', 'DOWNLOADING', 'PAUSED') LIMIT 1")
    suspend fun getActiveByUrl(url: String): DownloadEntity?

    @Insert(onConflict = OnConflictStrategy.REPLACE)
    suspend fun insert(download: DownloadEntity)

    @Update
    suspend fun update(download: DownloadEntity)

    @Query("UPDATE downloads SET progress = :progress, speed = :speed, eta = :eta, downloadedBytes = :downloaded, totalBytes = :total, status = :status WHERE id = :id")
    suspend fun updateProgress(
        id: String,
        progress: Float,
        speed: String,
        eta: String,
        downloaded: Long,
        total: Long,
        status: DownloadStatus
    )

    @Query("UPDATE downloads SET status = :status WHERE id = :id")
    suspend fun updateStatus(id: String, status: DownloadStatus)

    @Delete
    suspend fun delete(download: DownloadEntity)

    @Query("DELETE FROM downloads WHERE id = :id")
    suspend fun deleteById(id: String)

    @Query("DELETE FROM downloads WHERE status = 'COMPLETED'")
    suspend fun clearHistory()
}

package com.pullar.app.data.database

import android.content.Context
import androidx.room.Database
import androidx.room.Room
import androidx.room.RoomDatabase
import com.pullar.app.data.dao.DownloadDao
import com.pullar.app.data.model.DownloadEntity

@Database(entities = [DownloadEntity::class], version = 1, exportSchema = false)
abstract class PullarDatabase : RoomDatabase() {

    abstract fun downloadDao(): DownloadDao

    companion object {
        @Volatile
        private var INSTANCE: PullarDatabase? = null

        fun getDatabase(context: Context): PullarDatabase {
            return INSTANCE ?: synchronized(this) {
                val instance = Room.databaseBuilder(
                    context.applicationContext,
                    PullarDatabase::class.java,
                    "pullar_database"
                )
                    .fallbackToDestructiveMigration()
                    .build()
                INSTANCE = instance
                instance
            }
        }
    }
}

package com.pullar.app.core

import android.content.Context
import android.util.Log
import com.pullar.app.data.model.DownloadEntity
import com.pullar.app.data.model.FormatOption
import com.pullar.app.data.model.VideoMetadata
import com.yausername.youtubedl_android.YoutubeDL
import com.yausername.youtubedl_android.YoutubeDLException
import com.yausername.youtubedl_android.YoutubeDLRequest
import com.yausername.youtubedl_android.YoutubeDLResponse
import com.yausername.ffmpeg.FFmpeg
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.withContext
import java.io.File
import java.util.regex.Pattern

object YoutubeDLEngine {

    private const val TAG = "PullarYoutubeDL"
    private var isInitialized = false

    fun init(context: Context) {
        if (isInitialized) return
        try {
            YoutubeDL.getInstance().init(context.applicationContext)
            FFmpeg.getInstance().init(context.applicationContext)
            isInitialized = true
            Log.i(TAG, "YoutubeDL and FFmpeg initialized successfully.")
        } catch (e: Exception) {
            Log.e(TAG, "Failed to initialize YoutubeDL engine: ${e.message}", e)
        }
    }

    suspend fun updateEngine(context: Context): Boolean = withContext(Dispatchers.IO) {
        try {
            val status = YoutubeDL.getInstance().updateYoutubeDL(context.applicationContext, YoutubeDL.UpdateChannel._STABLE)
            Log.i(TAG, "YoutubeDL updated status: $status")
            true
        } catch (e: Exception) {
            Log.e(TAG, "Failed to update YoutubeDL: ${e.message}")
            false
        }
    }

    fun isPlaylistUrl(url: String): Boolean {
        return url.contains("list=") || url.contains("/playlist") || url.contains("/sets/")
    }

    suspend fun extractInfo(url: String): Result<VideoMetadata> = withContext(Dispatchers.IO) {
        try {
            val isPlaylist = isPlaylistUrl(url)
            val request = YoutubeDLRequest(url)
            request.addOption("--dump-single-json")
            request.addOption("--no-warnings")
            request.addOption("--flat-playlist")

            val response: YoutubeDLResponse = YoutubeDL.getInstance().execute(request)
            val output = response.out

            val titleMatch = Regex("\"title\"\\s*:\\s*\"([^\"]+)\"").find(output)
            val title = titleMatch?.groupValues?.get(1) ?: "Unknown Title"

            val uploaderMatch = Regex("\"uploader\"\\s*:\\s*\"([^\"]+)\"").find(output)
                ?: Regex("\"channel\"\\s*:\\s*\"([^\"]+)\"").find(output)
            val uploader = uploaderMatch?.groupValues?.get(1) ?: ""

            val durationMatch = Regex("\"duration\"\\s*:\\s*([0-9]+)").find(output)
            val durationSeconds = durationMatch?.groupValues?.get(1)?.toLongOrNull() ?: 0L
            val durationFormatted = formatDuration(durationSeconds)

            val thumbMatch = Regex("\"thumbnail\"\\s*:\\s*\"([^\"]+)\"").find(output)
            val thumbnailUrl = thumbMatch?.groupValues?.get(1) ?: ""

            val playlistCount = if (isPlaylist) {
                Regex("\"entries\"\\s*:\\s*\\[").findAll(output).count()
            } else 0

            val formats = listOf(
                FormatOption(
                    formatId = "bestvideo[ext=mp4]+bestaudio[ext=m4a]/best[ext=mp4]/best",
                    label = "Best Quality (MP4)",
                    resolution = "Highest Available",
                    extension = "mp4",
                    isAudioOnly = false,
                    note = "Full quality video with merged audio"
                ),
                FormatOption(
                    formatId = "bestvideo[height<=1080][ext=mp4]+bestaudio[ext=m4a]/best[height<=1080]",
                    label = "1080p FHD",
                    resolution = "1920x1080",
                    extension = "mp4",
                    isAudioOnly = false,
                    note = "High Definition"
                ),
                FormatOption(
                    formatId = "bestvideo[height<=720][ext=mp4]+bestaudio[ext=m4a]/best[height<=720]",
                    label = "720p HD",
                    resolution = "1280x720",
                    extension = "mp4",
                    isAudioOnly = false,
                    note = "Standard High Definition"
                ),
                FormatOption(
                    formatId = "bestvideo[height<=480][ext=mp4]+bestaudio[ext=m4a]/best[height<=480]",
                    label = "480p SD",
                    resolution = "854x480",
                    extension = "mp4",
                    isAudioOnly = false,
                    note = "Standard Definition"
                ),
                FormatOption(
                    formatId = "bestaudio/best",
                    label = "Audio Only (MP3)",
                    resolution = "Audio 320kbps",
                    extension = "mp3",
                    isAudioOnly = true,
                    note = "Extracted high quality MP3"
                )
            )

            Result.success(
                VideoMetadata(
                    url = url,
                    title = title,
                    uploader = uploader,
                    durationSeconds = durationSeconds,
                    durationFormatted = durationFormatted,
                    thumbnailUrl = thumbnailUrl,
                    isPlaylist = isPlaylist,
                    playlistCount = playlistCount,
                    availableFormats = formats
                )
            )
        } catch (e: Exception) {
            Log.e(TAG, "Extraction failed: ${e.message}", e)
            Result.failure(e)
        }
    }

    fun buildDownloadRequest(
        item: DownloadEntity,
        outputDirectory: File
    ): YoutubeDLRequest {
        val request = YoutubeDLRequest(item.url)

        val destinationTemplate = if (item.isPlaylist) {
            "${outputDirectory.absolutePath}/%(playlist_title)s/%(playlist_index)s - %(title)s.%(ext)s"
        } else {
            "${outputDirectory.absolutePath}/%(title)s.%(ext)s"
        }
        request.addOption("-o", destinationTemplate)

        // IDM-Style High-Speed Segmented Multi-Connection Scheme
        request.addOption("--concurrent-fragments", "16")
        request.addOption("--buffer-size", "1024K")
        request.addOption("--http-chunk-size", "10M")
        request.addOption("--retries", "10")
        request.addOption("--fragment-retries", "10")

        // Playlist enforcement
        if (item.isPlaylist) {
            request.addOption("--yes-playlist")
        } else {
            // Strictly enforce --no-playlist to prevent repeated loop downloading on single watch URLs
            request.addOption("--no-playlist")
        }

        // Format & Audio handling
        if (item.isAudioOnly) {
            request.addOption("-x")
            request.addOption("--audio-format", "mp3")
            request.addOption("--audio-quality", "0")
        } else {
            request.addOption("-f", item.formatId)
            request.addOption("--merge-output-format", "mp4")
        }

        request.addOption("--no-warnings")
        request.addOption("--no-check-certificates")
        return request
    }

    private fun formatDuration(seconds: Long): String {
        if (seconds <= 0) return ""
        val hrs = seconds / 3600
        val mins = (seconds % 3600) / 60
        val secs = seconds % 60
        return if (hrs > 0) {
            String.format("%d:%02d:%02d", hrs, mins, secs)
        } else {
            String.format("%d:%02d", mins, secs)
        }
    }
}

package com.pullar.app.service

import android.app.NotificationChannel
import android.app.NotificationManager
import android.app.PendingIntent
import android.app.Service
import android.content.Context
import android.content.Intent
import android.os.Build
import android.os.Environment
import android.os.IBinder
import android.util.Log
import androidx.core.app.NotificationCompat
import com.pullar.app.MainActivity
import com.pullar.app.R
import com.pullar.app.core.YoutubeDLEngine
import com.pullar.app.data.database.PullarDatabase
import com.pullar.app.data.model.DownloadEntity
import com.pullar.app.data.model.DownloadStatus
import com.yausername.youtubedl_android.YoutubeDL
import kotlinx.coroutines.CoroutineScope
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.Job
import kotlinx.coroutines.SupervisorJob
import kotlinx.coroutines.cancel
import kotlinx.coroutines.launch
import java.io.File

class DownloadForegroundService : Service() {

    private val serviceScope = CoroutineScope(SupervisorJob() + Dispatchers.IO)
    private var currentDownloadJob: Job? = null
    private var activeTaskId: String? = null
    private lateinit var notificationManager: NotificationManager

    companion object {
        const val CHANNEL_ID = "pullar_downloads"
        const val NOTIFICATION_ID = 1001

        const val ACTION_START_DOWNLOAD = "com.pullar.app.START_DOWNLOAD"
        const val ACTION_CANCEL_DOWNLOAD = "com.pullar.app.CANCEL_DOWNLOAD"
        const val EXTRA_TASK_ID = "extra_task_id"

        fun startDownload(context: Context, taskId: String) {
            val intent = Intent(context, DownloadForegroundService::class.java).apply {
                action = ACTION_START_DOWNLOAD
                putExtra(EXTRA_TASK_ID, taskId)
            }
            if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.O) {
                context.startForegroundService(intent)
            } else {
                context.startService(intent)
            }
        }

        fun cancelDownload(context: Context, taskId: String) {
            val intent = Intent(context, DownloadForegroundService::class.java).apply {
                action = ACTION_CANCEL_DOWNLOAD
                putExtra(EXTRA_TASK_ID, taskId)
            }
            context.startService(intent)
        }
    }

    override fun onCreate() {
        super.onCreate()
        notificationManager = getSystemService(Context.NOTIFICATION_SERVICE) as NotificationManager
        createNotificationChannel()
    }

    override fun onStartCommand(intent: Intent?, flags: Int, startId: Int): Int {
        when (intent?.action) {
            ACTION_START_DOWNLOAD -> {
                val taskId = intent.getStringExtra(EXTRA_TASK_ID)
                if (!taskId.isNullOrBlank()) {
                    startForeground(NOTIFICATION_ID, buildNotification("Starting download...", 0, ""))
                    processDownload(taskId)
                }
            }
            ACTION_CANCEL_DOWNLOAD -> {
                val taskId = intent.getStringExtra(EXTRA_TASK_ID)
                if (taskId != null && taskId == activeTaskId) {
                    cancelCurrentDownload()
                }
            }
        }
        return START_NOT_STICKY
    }

    private fun processDownload(taskId: String) {
        currentDownloadJob?.cancel()
        currentDownloadJob = serviceScope.launch {
            activeTaskId = taskId
            val db = PullarDatabase.getDatabase(applicationContext)
            val dao = db.downloadDao()
            val task = dao.getById(taskId)

            if (task == null) {
                stopSelf()
                return@launch
            }

            try {
                dao.updateStatus(taskId, DownloadStatus.DOWNLOADING)

                val downloadDir = Environment.getExternalStoragePublicDirectory(Environment.DIRECTORY_DOWNLOADS)
                val pullarDir = File(downloadDir, "Pullar")
                if (!pullarDir.exists()) {
                    pullarDir.mkdirs()
                }

                val request = YoutubeDLEngine.buildDownloadRequest(task, pullarDir)

                YoutubeDL.getInstance().execute(request, taskId) { progress, etaInSeconds, line ->
                    val speed = extractSpeed(line)
                    val etaFormatted = if (etaInSeconds > 0) "${etaInSeconds}s" else ""

                    notificationManager.notify(
                        NOTIFICATION_ID,
                        buildNotification(task.title, progress.toInt(), speed)
                    )

                    serviceScope.launch {
                        dao.updateProgress(
                            id = taskId,
                            progress = progress,
                            speed = speed,
                            eta = etaFormatted,
                            downloaded = 0L,
                            total = 0L,
                            status = DownloadStatus.DOWNLOADING
                        )
                    }
                }

                // Download completed
                dao.updateProgress(
                    id = taskId,
                    progress = 100f,
                    speed = "Completed",
                    eta = "",
                    downloaded = 0L,
                    total = 0L,
                    status = DownloadStatus.COMPLETED
                )

                showCompletionNotification(task.title)

            } catch (e: Exception) {
                Log.e("DownloadService", "Download error: ${e.message}", e)
                dao.updateStatus(taskId, DownloadStatus.FAILED)
            } finally {
                activeTaskId = null
                stopForeground(STOP_FOREGROUND_DETACH)
                stopSelf()
            }
        }
    }

    private fun cancelCurrentDownload() {
        val taskId = activeTaskId
        currentDownloadJob?.cancel()
        if (taskId != null) {
            YoutubeDL.getInstance().destroyProcessById(taskId)
            serviceScope.launch {
                val db = PullarDatabase.getDatabase(applicationContext)
                db.downloadDao().updateStatus(taskId, DownloadStatus.CANCELLED)
            }
        }
        stopForeground(STOP_FOREGROUND_REMOVE)
        stopSelf()
    }

    private fun extractSpeed(line: String): String {
        val speedMatch = Regex("([0-9.]+\\s*(?:KiB|MiB|GiB|KB|MB|GB)/s)").find(line)
        return speedMatch?.groupValues?.get(1) ?: ""
    }

    private fun buildNotification(title: String, progress: Int, speed: String): android.app.Notification {
        val launchIntent = Intent(this, MainActivity::class.java)
        val pendingIntent = PendingIntent.getActivity(
            this,
            0,
            launchIntent,
            PendingIntent.FLAG_UPDATE_CURRENT or PendingIntent.FLAG_IMMUTABLE
        )

        val contentText = if (speed.isNotBlank()) "$progress% • $speed" else "$progress%"

        return NotificationCompat.Builder(this, CHANNEL_ID)
            .setContentTitle(title)
            .setContentText(contentText)
            .setSmallIcon(R.drawable.ic_launcher_foreground)
            .setProgress(100, progress, progress == 0)
            .setOngoing(true)
            .setContentIntent(pendingIntent)
            .build()
    }

    private fun showCompletionNotification(title: String) {
        val launchIntent = Intent(this, MainActivity::class.java)
        val pendingIntent = PendingIntent.getActivity(
            this,
            1,
            launchIntent,
            PendingIntent.FLAG_UPDATE_CURRENT or PendingIntent.FLAG_IMMUTABLE
        )

        val completionNotification = NotificationCompat.Builder(this, CHANNEL_ID)
            .setContentTitle("Download Finished")
            .setContentText(title)
            .setSmallIcon(R.drawable.ic_launcher_foreground)
            .setAutoCancel(true)
            .setContentIntent(pendingIntent)
            .build()

        notificationManager.notify(System.currentTimeMillis().toInt(), completionNotification)
    }

    private fun createNotificationChannel() {
        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.O) {
            val channel = NotificationChannel(
                CHANNEL_ID,
                getString(R.string.channel_name),
                NotificationManager.IMPORTANCE_LOW
            ).apply {
                description = getString(R.string.channel_description)
                setShowBadge(false)
            }
            notificationManager.createNotificationChannel(channel)
        }
    }

    override fun onBind(intent: Intent?): IBinder? = null

    override fun onDestroy() {
        super.onDestroy()
        serviceScope.cancel()
    }
}

