@OptIn(UnstableApi::class)
@Composable
fun MediaPlayerScreen(
    mediaUriString: String,
    onBack: () -> Unit
) {
    val context = LocalContext.current

    val exoPlayer = remember {
        ExoPlayer.Builder(context).build().apply {
            val uri = if (mediaUriString.startsWith("http://") || mediaUriString.startsWith("https://") || mediaUriString.startsWith("content://")) {
                Uri.parse(mediaUriString)
            } else {
                Uri.fromFile(File(mediaUriString))
            }
            setMediaItem(MediaItem.fromUri(uri))
            prepare()
            playWhenReady = true
        }
    }

    DisposableEffect(Unit) {
        onDispose {
            exoPlayer.release()
        }
    }

    Box(
        modifier = Modifier
            .fillMaxSize()
            .background(CoffeeBean)
    ) {
        AndroidView(
            factory = { ctx ->
                PlayerView(ctx).apply {
                    player = exoPlayer
                    useController = true
                    layoutParams = FrameLayout.LayoutParams(
                        ViewGroup.LayoutParams.MATCH_PARENT,
                        ViewGroup.LayoutParams.MATCH_PARENT
                    )
                }
            },
            modifier = Modifier.fillMaxSize()
        )

        // Top Back Button
        IconButton(
            onClick = onBack,
            modifier = Modifier
                .padding(top = 28.dp, start = 16.dp)
                .size(48.dp)
                .align(Alignment.TopStart)
        ) {
            Icon(
                Icons.AutoMirrored.Filled.ArrowBack,
                contentDescription = "Back",
                tint = LightApricot
            )
        }
    }
}

