import com.pullar.app.ui.theme.ToffeeBrown
import java.net.URLDecoder

data class NavItem(
    val route: String,
    val title: String,
    val icon: ImageVector
)

@Composable
fun PullarApp(
    navController: NavHostController = rememberNavController(),
    sharedUrl: String? = null
) {
    val navBackStackEntry by navController.currentBackStackEntryAsState()
    val currentRoute = navBackStackEntry?.destination?.route

    val navItems = listOf(
        NavItem(Screen.Downloader.route, "Downloader", Icons.Default.Home),
        NavItem(Screen.Downloads.route, "Downloads", Icons.Default.Download),
        NavItem(Screen.History.route, "History", Icons.Default.History),
        NavItem(Screen.Settings.route, "Settings", Icons.Default.Settings)
    )

    val showBottomBar = currentRoute in navItems.map { it.route }

    Scaffold(
        bottomBar = {
            if (showBottomBar) {
                NavigationBar(
                    containerColor = SurfaceCard,
                    contentColor = LightApricot
                ) {
                    navItems.forEach { item ->
                        val selected = currentRoute == item.route
                        NavigationBarItem(
                            selected = selected,
                            onClick = {
                                navController.navigate(item.route) {
                                    popUpTo(navController.graph.findStartDestination().id) {
                                        saveState = true
                                    }
                                    launchSingleTop = true
                                    restoreState = true
                                }
                            },
                            icon = { Icon(item.icon, contentDescription = item.title) },
                            label = { Text(item.title) },
                            colors = NavigationBarItemDefaults.colors(
                                selectedIconColor = CoffeeBean,
                                selectedTextColor = MayaBlue,
                                indicatorColor = MayaBlue,
                                unselectedIconColor = TextMuted,
                                unselectedTextColor = TextMuted
                            )
                        )
                    }
                }
            }
        },
        containerColor = CoffeeBean
    ) { innerPadding ->
        NavHost(
            navController = navController,
            startDestination = Screen.Downloader.route,
            modifier = Modifier.padding(innerPadding)
        ) {
            composable(Screen.Downloader.route) {
                DownloaderScreen(
                    onNavigateToDownloads = {
                        navController.navigate(Screen.Downloads.route) {
                            popUpTo(navController.graph.findStartDestination().id) {
                                saveState = true
                            }
                            launchSingleTop = true
                            restoreState = true
                        }
                    }
                )
            }

            composable(Screen.Downloads.route) {
                DownloadsScreen(
                    onPlayMedia = { path ->
                        navController.navigate(Screen.Player.createRoute(path))
                    }
                )
            }

            composable(Screen.History.route) {
                HistoryScreen(
                    onPlayMedia = { path ->
                        navController.navigate(Screen.Player.createRoute(path))
                    }
                )
            }

            composable(Screen.Settings.route) {
                SettingsScreen()
            }

            composable(
                route = Screen.Player.route,
                arguments = listOf(navArgument("videoUri") { type = NavType.StringType })
            ) { backStackEntry ->
                val encodedUri = backStackEntry.arguments?.getString("videoUri") ?: ""
                val decodedUri = URLDecoder.decode(encodedUri, "UTF-8")
                MediaPlayerScreen(
                    mediaUriString = decodedUri,
                    onBack = { navController.popBackStack() }
                )
            }
        }
    }
}

package com.pullar.app

import android.content.Intent
import android.os.Bundle
import androidx.activity.ComponentActivity
import androidx.activity.compose.setContent
import androidx.activity.enableEdgeToEdge
import com.pullar.app.ui.navigation.PullarApp
import com.pullar.app.ui.theme.PullarTheme

class MainActivity : ComponentActivity() {

    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        enableEdgeToEdge()

        val sharedUrl = handleIncomingIntent(intent)

        setContent {
            PullarTheme {
                PullarApp(sharedUrl = sharedUrl)
            }
        }
    }

    override fun onNewIntent(intent: Intent) {
        super.onNewIntent(intent)
        setIntent(intent)
        handleIncomingIntent(intent)
    }

    private fun handleIncomingIntent(intent: Intent?): String? {
        if (intent?.action == Intent.ACTION_SEND && intent.type == "text/plain") {
            return intent.getStringExtra(Intent.EXTRA_TEXT)
        }
        return null
    }
}

